package config

import (
	"bytes"
	"errors"
	"fmt"
	"os"
	"path/filepath"

	"gopkg.in/yaml.v3"
)

// Path returns the resolved config file path.
// Resolution order: WIRE_CONFIG env var → XDG_CONFIG_HOME/wire/config.yaml →
// ~/.config/wire/config.yaml.
func Path() string {
	if v := os.Getenv("WIRE_CONFIG"); v != "" {
		return v
	}
	base := os.Getenv("XDG_CONFIG_HOME")
	if base == "" {
		home, _ := os.UserHomeDir()
		base = filepath.Join(home, ".config")
	}
	return filepath.Join(base, "wire", "config.yaml")
}

type Config struct {
	Listen    string                 `yaml:"listen"`
	Monitor   bool                   `yaml:"monitor"`
	MaxModels int                    `yaml:"max_models"`
	Models    map[string]ModelParams `yaml:"models"`
	Warmup    []string               `yaml:"warmup"`
}

type ModelParams struct {
	Context    int      `yaml:"context"`
	GPULayers  int      `yaml:"gpu_layers"`
	Slots      int      `yaml:"slots"`
	Pooling    string   `yaml:"pooling"`
	Extra      []string `yaml:"extra"`
	SpecType   string   `yaml:"spec_type"`
	DraftMax   int      `yaml:"draft_max"`
	DraftMin   int      `yaml:"draft_min"`
	SpecNgramN int      `yaml:"spec_ngram_n"`
	SpecNgramM int      `yaml:"spec_ngram_m"`
}

// MatchModel returns the ModelParams for the first glob pattern in Models that
// matches name. Returns zero ModelParams and false if no pattern matches.
func (c *Config) MatchModel(name string) (ModelParams, bool) {
	for pattern, params := range c.Models {
		matched, err := filepath.Match(pattern, name)
		if err == nil && matched {
			return params, true
		}
	}
	return ModelParams{}, false
}

// Load reads the config from disk, applies defaults, and validates it.
func Load() (*Config, error) {
	path := Path()

	data, err := os.ReadFile(path)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil, fmt.Errorf("config file not found at %s: %w", path, err)
		}
		return nil, fmt.Errorf("reading config %s: %w", path, err)
	}

	cfg := new(Config)
	dec := yaml.NewDecoder(bytes.NewReader(data))
	dec.KnownFields(true)
	if err := dec.Decode(cfg); err != nil {
		return nil, fmt.Errorf("parsing config %s: %w", path, err)
	}

	applyDefaults(cfg)

	if err := validate(cfg); err != nil {
		return nil, err
	}

	return cfg, nil
}

func applyDefaults(cfg *Config) {
	if cfg.Listen == "" {
		cfg.Listen = ":9480"
	}
	if cfg.MaxModels == 0 {
		cfg.MaxModels = 1
	}
	for pattern, p := range cfg.Models {
		if p.Slots == 0 {
			p.Slots = 1
			cfg.Models[pattern] = p
		}
	}
}

func validate(cfg *Config) error {
	for _, entry := range cfg.Warmup {
		var matches int
		for pattern := range cfg.Models {
			matched, err := filepath.Match(pattern, entry)
			if err == nil && matched {
				matches++
			}
		}
		if matches == 0 {
			return fmt.Errorf("warmup entry %q does not match any model pattern", entry)
		}
		if matches > 1 {
			return fmt.Errorf("warmup entry %q matches %d model patterns (expected 1)", entry, matches)
		}
	}
	if len(cfg.Warmup) > cfg.MaxModels {
		return fmt.Errorf("warmup list length %d exceeds max_models %d", len(cfg.Warmup), cfg.MaxModels)
	}
	validSpecTypes := map[string]bool{
		"ngram-simple":  true,
		"ngram-mod":     true,
		"ngram-cache":   true,
		"ngram-map-k":   true,
		"ngram-map-k4v": true,
	}
	for pattern, p := range cfg.Models {
		if p.SpecType != "" && !validSpecTypes[p.SpecType] {
			return fmt.Errorf("model pattern %q: invalid spec_type %q (valid: ngram-simple, ngram-mod, ngram-cache, ngram-map-k, ngram-map-k4v)", pattern, p.SpecType)
		}
	}
	return nil
}

package config

import (
	"context"
	"log/slog"
	"path/filepath"
	"time"

	"github.com/fsnotify/fsnotify"
)

const debounceDuration = 500 * time.Millisecond

// Watch monitors the config file for changes and emits validated *Config values
// on the returned channel. The channel is closed when ctx is cancelled.
// Invalid configs are logged and discarded; the running config is never replaced
// with a broken one.
//
// The watcher targets the directory containing the config file so that
// editor write-rename patterns (vim, sed -i) are detected correctly — they
// delete the inode, which breaks file-level watches.
func Watch(ctx context.Context, log *slog.Logger) (<-chan *Config, error) {
	path := Path()
	dir := filepath.Dir(path)
	base := filepath.Base(path)

	watcher, err := fsnotify.NewWatcher()
	if err != nil {
		return nil, err
	}
	if err := watcher.Add(dir); err != nil {
		watcher.Close()
		return nil, err
	}

	ch := make(chan *Config, 1)

	go func() {
		defer close(ch)
		defer watcher.Close()

		var timer *time.Timer
		var timerC <-chan time.Time

		for {
			select {
			case <-ctx.Done():
				if timer != nil {
					timer.Stop()
				}
				return

			case event, ok := <-watcher.Events:
				if !ok {
					return
				}
				if filepath.Base(event.Name) != base {
					continue
				}
				if timer != nil {
					timer.Stop()
				}
				timer = time.NewTimer(debounceDuration)
				timerC = timer.C

			case <-timerC:
				timerC = nil
				timer = nil
				cfg, err := Load()
				if err != nil {
					log.Error("config reload failed", "err", err)
					continue
				}
				select {
				case ch <- cfg:
				default:
					log.Warn("config channel full, dropping reload")
				}

			case err, ok := <-watcher.Errors:
				if !ok {
					return
				}
				log.Error("fsnotify error", "err", err)
			}
		}
	}()

	return ch, nil
}

